aispBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "aispBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "MokkenLab",
                name = "aisp",
                version = c(1,0,0),
                options = options,
                results = aispResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Automated Item Selection
#'
#' Partitions a set of items into Mokken scales with Mokken's automated item 
#' selection procedure or a genetic algorithm, at one lower bound or across a 
#' sequence of lower bounds, with the scalability of every scale found and 
#' plain-language interpretation.
#' 
#' @param data .
#' @param vars .
#' @param clusterVar .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showGuides .
#' @param showRepro .
#' @param naHandling .
#' @param twowaySets .
#' @param twowaySeed .
#' @param scoreRange .
#' @param scoreMin .
#' @param scoreMax .
#' @param negItems .
#' @param lbMode .
#' @param lowerbound .
#' @param lbFrom .
#' @param lbTo .
#' @param lbStep .
#' @param search .
#' @param popsize .
#' @param maxgensMode .
#' @param maxgens .
#' @param pxover .
#' @param pmutation .
#' @param gaSeed .
#' @param alpha .
#' @param typeZ .
#' @param testHi .
#' @param startSet .
#' @param bootStability .
#' @param bootReps .
#' @param bootSeed .
#' @param bootPlot .
#' @param scaleCoefs .
#' @param scalePlot .
#' @param sequencePlot .
#' @param plotWidth .
#' @param plotHeight .
#' @param plotPointSize .
#' @param plotLineWidth .
#' @param plotNcol .
#' @param plotLegend .
#' @param plotAxisAngle .
#' @param plotYRange .
#' @param plotValueLabels .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$cacheStore} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$aispGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scales} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootPlotImg} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$sequenceGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$sequence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sequenceSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$scalePlotImg} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$sequencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibility} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$reproducibilityCode} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
aisp <- function(
    data,
    vars,
    clusterVar = NULL,
    showKeySummary = TRUE,
    showChoicesGuide = FALSE,
    showGuides = FALSE,
    showRepro = TRUE,
    naHandling = "listwise",
    twowaySets = 1,
    twowaySeed = 2026,
    scoreRange = "observed",
    scoreMin = 0,
    scoreMax = 4,
    negItems = list(),
    lbMode = "single",
    lowerbound = 0.3,
    lbFrom = 0.05,
    lbTo = 0.6,
    lbStep = 0.05,
    search = "normal",
    popsize = 20,
    maxgensMode = "auto",
    maxgens = 1000,
    pxover = 0.5,
    pmutation = 0.1,
    gaSeed = 2026,
    alpha = 0.05,
    typeZ = "Z",
    testHi = FALSE,
    startSet = list(),
    bootStability = FALSE,
    bootReps = 100,
    bootSeed = 2026,
    bootPlot = TRUE,
    scaleCoefs = TRUE,
    scalePlot = TRUE,
    sequencePlot = TRUE,
    plotWidth = 0,
    plotHeight = 0,
    plotPointSize = 2,
    plotLineWidth = 0.8,
    plotNcol = 0,
    plotLegend = "bottom",
    plotAxisAngle = "a45",
    plotYRange = "full",
    plotValueLabels = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("aisp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(clusterVar)) clusterVar <- jmvcore::resolveQuo(jmvcore::enquo(clusterVar))
    if ( ! missing(negItems)) negItems <- jmvcore::resolveQuo(jmvcore::enquo(negItems))
    if ( ! missing(startSet)) startSet <- jmvcore::resolveQuo(jmvcore::enquo(startSet))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(clusterVar), clusterVar, NULL),
            `if`( ! missing(negItems), negItems, NULL),
            `if`( ! missing(startSet), startSet, NULL))


    options <- aispOptions$new(
        vars = vars,
        clusterVar = clusterVar,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showGuides = showGuides,
        showRepro = showRepro,
        naHandling = naHandling,
        twowaySets = twowaySets,
        twowaySeed = twowaySeed,
        scoreRange = scoreRange,
        scoreMin = scoreMin,
        scoreMax = scoreMax,
        negItems = negItems,
        lbMode = lbMode,
        lowerbound = lowerbound,
        lbFrom = lbFrom,
        lbTo = lbTo,
        lbStep = lbStep,
        search = search,
        popsize = popsize,
        maxgensMode = maxgensMode,
        maxgens = maxgens,
        pxover = pxover,
        pmutation = pmutation,
        gaSeed = gaSeed,
        alpha = alpha,
        typeZ = typeZ,
        testHi = testHi,
        startSet = startSet,
        bootStability = bootStability,
        bootReps = bootReps,
        bootSeed = bootSeed,
        bootPlot = bootPlot,
        scaleCoefs = scaleCoefs,
        scalePlot = scalePlot,
        sequencePlot = sequencePlot,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        plotPointSize = plotPointSize,
        plotLineWidth = plotLineWidth,
        plotNcol = plotNcol,
        plotLegend = plotLegend,
        plotAxisAngle = plotAxisAngle,
        plotYRange = plotYRange,
        plotValueLabels = plotValueLabels)

    analysis <- aispClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

